#define OS08G10_REG_AGAIN_LCG_L		0x3589 /* bits [7:4]: RealGain[3:0] */
#define OS08G10_REG_DGAIN_LCG_H		0x358a /* bits [3:0]: DigitalGain[13:10] */
#define OS08G10_REG_DGAIN_LCG_M		0x358b /* bits [7:0]: DigitalGain[9:2] */
